import { NextResponse } from 'next/server';

type Post = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
};

type CreatePostBody = {
  title?: string;
  content?: string;
};

export async function GET() {
  const posts: Post[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ];

  return NextResponse.json(posts);
}

export async function POST(request: Request) {
  let body: CreatePostBody;

  try {
    body = (await request.json()) as CreatePostBody;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const { title, content } = body;

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    );
  }

  const newPost: Post = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(newPost, { status: 201 });
}
import { NextResponse } from 'next/server';

type UpdatePostBody = {
  title?: string;
  content?: string;
};

type RouteParams = {
  params: Promise<{ id: string }>;
};

function parseId(rawId: string): number | null {
  const id = Number.parseInt(rawId, 10);
  return Number.isNaN(id) ? null : id;
}

export async function GET(_request: Request, { params }: RouteParams) {
  const { id: rawId } = await params;
  const id = parseId(rawId);

  if (id === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post = {
    id,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(request: Request, { params }: RouteParams) {
  const { id: rawId } = await params;
  const id = parseId(rawId);

  if (id === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const { title, content } = body;

  const updatedPost = {
    id,
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(_request: Request, { params }: RouteParams) {
  const { id: rawId } = await params;
  const id = parseId(rawId);

  if (id === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json({ message: `Post ${id} deleted successfully` });
}
'use client';

import { createContext, useContext, useState } from 'react';

type Theme = 'light' | 'dark';

type AppContextValue = {
  theme: Theme;
  setTheme: (theme: Theme) => void;
};

const AppContext = createContext<AppContextValue | undefined>(undefined);

export function AppProvider({ children }: { children: React.ReactNode }) {
  const [theme, setTheme] = useState<Theme>('light');

  return (
    <AppContext.Provider value={{ theme, setTheme }}>
      {children}
    </AppContext.Provider>
  );
}

export function useAppContext() {
  const context = useContext(AppContext);

  if (!context) {
    throw new Error('useAppContext must be used within AppProvider');
  }

  return context;
}
export interface BlogPost {
  userId: number;
  id: number;
  title: string;
  body: string;
}

export interface BlogComment {
  postId: number;
  id: number;
  name: string;
  email: string;
  body: string;
}

const JSON_PLACEHOLDER_BASE_URL = 'https://jsonplaceholder.typicode.com';

async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);

  if (!response.ok) {
    throw new Error(`Request failed: ${response.status} ${response.statusText}`);
  }

  return response.json() as Promise<T>;
}

export async function getRecentPosts(
  limit: number,
  init?: RequestInit
): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(
    `${JSON_PLACEHOLDER_BASE_URL}/posts?_limit=${limit}`,
    init
  );
}

export async function getAllPosts(init?: RequestInit): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${JSON_PLACEHOLDER_BASE_URL}/posts`, init);
}

export async function getPostById(
  id: string,
  init?: RequestInit
): Promise<BlogPost | null> {
  const response = await fetch(`${JSON_PLACEHOLDER_BASE_URL}/posts/${id}`, init);

  if (!response.ok) {
    return null;
  }

  const post = (await response.json()) as Partial<BlogPost>;

  if (
    typeof post.id !== 'number' ||
    typeof post.title !== 'string' ||
    typeof post.body !== 'string'
  ) {
    return null;
  }

  return post as BlogPost;
}

export async function getPostComments(
  id: string,
  init?: RequestInit
): Promise<BlogComment[]> {
  return fetchJson<BlogComment[]>(
    `${JSON_PLACEHOLDER_BASE_URL}/posts/${id}/comments`,
    init
  );
}

